import { ChangeEvent, useEffect, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Copy, Eye, EyeOff, ImagePlus, Pencil, Plus, Star, Trash2, X } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

type Image = { id: string; public_url: string; storage_path: string; is_cover: boolean };
type Draft = { id?: string; name: string; price: string; duration: string; photography_type: string; team_size: string; team_size_custom: string; edited_photos: string; raw_photos_included: boolean; album_included: boolean; album_type: string; album_size: string; album_pages: string; travel_included: boolean; travel_radius_km: string; travel_extra_charge: string; delivery_time: string; status: string; description: string; highlights: string[]; highlightInput: string; addons: { name: string; price: string }[]; files: File[]; images: Image[] };
const empty = (): Draft => ({ name: '', price: '', duration: '', photography_type: 'Wedding', team_size: '1', team_size_custom: '', edited_photos: '', raw_photos_included: false, album_included: false, album_type: '', album_size: '', album_pages: '', travel_included: false, travel_radius_km: '', travel_extra_charge: '', delivery_time: '7-10 days', status: 'draft', description: '', highlights: [], highlightInput: '', addons: [], files: [], images: [] });
const num = (value: string) => value === '' ? null : Number(value);

export default function PhotographerPackageManager({ provider }: { provider: any }) {
  const { user } = useAuth(); const qc = useQueryClient(); const [draft, setDraft] = useState<Draft | null>(null); const [busy, setBusy] = useState(false);
  const { data: packages = [], isLoading } = useQuery({ queryKey: ['photography-packages', provider.id], queryFn: async () => { const { data, error } = await supabase.from('photography_packages' as any).select('*, photography_package_images(*), photography_package_highlights(*), photography_package_addons(*)').eq('photographer_id', provider.id).order('created_at', { ascending: false }); if (error) throw error; return data ?? []; } });
  const refresh = () => qc.invalidateQueries({ queryKey: ['photography-packages', provider.id] });
  useEffect(() => { const ch = supabase.channel(`photographer-packages-${provider.id}`).on('postgres_changes', { event: '*', schema: 'public', table: 'photography_packages', filter: `photographer_id=eq.${provider.id}` }, refresh).on('postgres_changes', { event: '*', schema: 'public', table: 'photography_package_images' }, refresh).subscribe(); return () => { supabase.removeChannel(ch); }; }, [provider.id]);
  const edit = (p: any) => setDraft({ id: p.id, name: p.name, price: String(p.price), duration: p.duration ?? '', photography_type: p.photography_type ?? 'Wedding', team_size: p.team_size === 0 ? 'custom' : String(p.team_size ?? '1'), team_size_custom: String(p.team_size_custom ?? ''), edited_photos: String(p.edited_photos ?? ''), raw_photos_included: !!p.raw_photos_included, album_included: !!p.album_included, album_type: p.album_type ?? '', album_size: p.album_size ?? '', album_pages: String(p.album_pages ?? ''), travel_included: !!p.travel_included, travel_radius_km: String(p.travel_radius_km ?? ''), travel_extra_charge: String(p.travel_extra_charge ?? ''), delivery_time: p.delivery_time ?? '7-10 days', status: p.status ?? (p.is_visible ? 'published' : 'draft'), description: p.description ?? '', highlights: (p.photography_package_highlights ?? []).map((x: any) => x.text), highlightInput: '', addons: (p.photography_package_addons ?? []).map((x: any) => ({ name: x.name, price: String(x.price) })), files: [], images: p.photography_package_images ?? [] });
  const upload = async (packageId: string, files: File[]) => { if (!user) return; for (const [i, file] of files.entries()) { if (!file.type.startsWith('image/') || file.size > 8 * 1024 * 1024) throw new Error('Use image files under 8MB'); const path = `${user.id}/${packageId}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, '_')}`; const { error } = await supabase.storage.from('photography-package-images').upload(path, file, { contentType: file.type }); if (error) throw error; const { data } = supabase.storage.from('photography-package-images').getPublicUrl(path); const result = await supabase.from('photography_package_images' as any).insert({ package_id: packageId, storage_path: path, public_url: data.publicUrl, alt_text: file.name, is_cover: i === 0 && !draft?.images.length, sort_order: i }); if (result.error) throw result.error; } };
  const save = async () => { if (!draft || !draft.name.trim() || !draft.price || Number(draft.price) < 0 || !draft.duration || (draft.team_size === 'custom' && (!draft.team_size_custom || Number(draft.team_size_custom) < 1))) { toast.error('Name, price, duration and a valid team size are required.'); return; } setBusy(true); try { const published = draft.status === 'published'; const payload = { photographer_id: provider.id, name: draft.name.trim(), price: Number(draft.price), duration: draft.duration || null, photography_type: draft.photography_type, team_size: draft.team_size === 'custom' ? 0 : Number(draft.team_size), team_size_custom: draft.team_size === 'custom' ? Number(draft.team_size_custom) : null, edited_photos: num(draft.edited_photos), raw_photos_included: draft.raw_photos_included, album_included: draft.album_included, album_type: draft.album_included ? draft.album_type || null : null, album_size: draft.album_included ? draft.album_size || null : null, album_pages: draft.album_included ? num(draft.album_pages) : null, travel_included: draft.travel_included, travel_radius_km: draft.travel_included ? num(draft.travel_radius_km) : null, travel_extra_charge: draft.travel_included ? num(draft.travel_extra_charge) : null, delivery_time: draft.delivery_time || null, status: draft.status, description: draft.description || null, is_active: draft.status !== 'archived', is_visible: published }; const r = draft.id ? await supabase.from('photography_packages' as any).update(payload).eq('id', draft.id).select().single() : await supabase.from('photography_packages' as any).insert(payload).select().single(); if (r.error) throw r.error; const id = r.data.id; if (draft.id) { await supabase.from('photography_package_highlights' as any).delete().eq('package_id', id); await supabase.from('photography_package_addons' as any).delete().eq('package_id', id); } if (draft.highlights.length) { const { error } = await supabase.from('photography_package_highlights' as any).insert(draft.highlights.map((text, sort_order) => ({ package_id: id, text, sort_order }))); if (error) throw error; } const addons = draft.addons.filter(a => a.name.trim() && a.price !== '').map((a, sort_order) => ({ package_id: id, name: a.name.trim(), price: Number(a.price), sort_order })); if (addons.length) { const { error } = await supabase.from('photography_package_addons' as any).insert(addons); if (error) throw error; } await upload(id, draft.files); toast.success('Photography package saved'); setDraft(null); refresh(); } catch (error: any) { toast.error(error.message || 'Could not save package'); } finally { setBusy(false); } };
  const setCover = async (image: Image) => { if (!draft?.id) return; const { error } = await supabase.from('photography_package_images' as any).update({ is_cover: false }).eq('package_id', draft.id); if (!error) await supabase.from('photography_package_images' as any).update({ is_cover: true }).eq('id', image.id); if (error) toast.error(error.message); else { setDraft(d => d && ({ ...d, images: d.images.map(x => ({ ...x, is_cover: x.id === image.id })) })); refresh(); } };
  const removeImage = async (image: Image) => { if (!confirm('Remove this image?')) return; const { error } = await supabase.from('photography_package_images' as any).delete().eq('id', image.id); if (!error) await supabase.storage.from('photography-package-images').remove([image.storage_path]); if (error) toast.error(error.message); else setDraft(d => d && ({ ...d, images: d.images.filter(x => x.id !== image.id) })); };
  const action = async (p: any, actionName: 'delete' | 'visibility' | 'duplicate') => { if (actionName === 'delete' && !confirm('Delete this package? Existing bookings remain preserved.')) return; const request = actionName === 'delete' ? supabase.from('photography_packages' as any).delete().eq('id', p.id) : actionName === 'visibility' ? supabase.from('photography_packages' as any).update({ status: p.status === 'published' ? 'draft' : 'published', is_visible: p.status !== 'published', is_active: true }).eq('id', p.id) : supabase.from('photography_packages' as any).insert({ photographer_id: provider.id, name: `${p.name} (Copy)`, price: p.price, duration: p.duration, photography_type: p.photography_type, team_size: p.team_size, status: 'draft', is_visible: false, is_active: true }); const { error } = await request; if (error) toast.error(error.message); else { toast.success(actionName === 'duplicate' ? 'Draft duplicated' : 'Package updated'); refresh(); } };
  return <div className="max-w-[1200px] space-y-6"><div className="flex flex-wrap justify-between gap-3"><div><h1 className="text-xl font-bold">Photography Packages</h1><p className="text-sm text-muted-foreground">Build polished packages customers can compare and book.</p></div><button onClick={() => setDraft(empty())} className="rounded-xl bg-[#8B1538] px-4 py-2.5 text-sm font-semibold text-white"><Plus className="mr-1 inline h-4 w-4" />Create package</button></div>{isLoading ? <div className="h-48 animate-pulse rounded-2xl bg-muted" /> : <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{packages.map((p: any) => { const image = p.photography_package_images?.find((x: any) => x.is_cover) ?? p.photography_package_images?.[0]; return <div key={p.id} className="overflow-hidden rounded-2xl border bg-white"><div className="h-36 bg-secondary">{image && <img src={image.public_url} alt="" className="h-full w-full object-cover" />}</div><div className="p-4"><div className="flex justify-between gap-2"><h2 className="font-bold">{p.name}</h2><span className="text-xs font-semibold uppercase text-muted-foreground">{p.status}</span></div><p className="mt-1 text-lg font-bold">₹{Number(p.price).toLocaleString('en-IN')}</p><p className="text-xs text-muted-foreground">{p.photography_type || 'Photography'} · {p.duration || 'Duration not set'} · {p.team_size_custom || p.team_size || 1} member team</p><div className="mt-4 flex gap-2"><button onClick={() => edit(p)} className="flex-1 rounded-lg border py-2 text-xs"><Pencil className="mr-1 inline h-3" />Edit</button><button onClick={() => action(p, 'duplicate')} aria-label="Duplicate" className="rounded-lg border p-2"><Copy className="h-3" /></button><button onClick={() => action(p, 'visibility')} aria-label="Toggle publication" className="rounded-lg border p-2">{p.status === 'published' ? <EyeOff className="h-3" /> : <Eye className="h-3" />}</button><button onClick={() => action(p, 'delete')} aria-label="Delete" className="rounded-lg border border-red-200 p-2 text-red-600"><Trash2 className="h-3" /></button></div></div></div>; })}</div>}{draft && <Editor draft={draft} setDraft={setDraft} save={save} close={() => setDraft(null)} busy={busy} setCover={setCover} removeImage={removeImage} />}</div>;
}
function Editor({ draft: d, setDraft, save, close, busy, setCover, removeImage }: any) { const patch = (value: Partial<Draft>) => setDraft((old: Draft) => ({ ...old, ...value })); const addHighlight = () => { const text = d.highlightInput.trim(); if (text && !d.highlights.includes(text)) patch({ highlights: [...d.highlights, text], highlightInput: '' }); }; return <div className="fixed inset-0 z-[70] overflow-y-auto bg-black/50 p-4"><div className="mx-auto max-w-3xl space-y-4 rounded-2xl bg-white p-6"><div className="flex justify-between"><h2 className="font-bold">{d.id ? 'Edit' : 'Create'} photography package</h2><button onClick={close}><X className="h-5" /></button></div><div className="grid gap-3 sm:grid-cols-2"><Field label="Package name *"><input value={d.name} onChange={e => patch({ name: e.target.value })} /></Field><Field label="Price (₹) *"><input type="number" min="0" value={d.price} onChange={e => patch({ price: e.target.value })} /></Field><Field label="Photography type *"><select value={d.photography_type} onChange={e => patch({ photography_type: e.target.value })}>{['Wedding', 'Pre-wedding', 'Birthday', 'Corporate', 'Portrait', 'Product', 'Other'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Duration *"><select value={d.duration} onChange={e => patch({ duration: e.target.value })}><option value="">Select duration</option>{['2 hours', '4 hours', '6 hours', '8 hours', 'Full day', 'Custom'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Team size *"><select value={d.team_size} onChange={e => patch({ team_size: e.target.value })}>{['1', '2', '3', '4', 'custom'].map(x => <option key={x} value={x}>{x === 'custom' ? 'Custom' : `${x} member${x === '1' ? '' : 's'}`}</option>)}</select></Field>{d.team_size === 'custom' && <Field label="Custom team size *"><input type="number" min="1" value={d.team_size_custom} onChange={e => patch({ team_size_custom: e.target.value })} /></Field>}<Field label="Edited photos"><input type="number" min="0" value={d.edited_photos} onChange={e => patch({ edited_photos: e.target.value })} /></Field><Field label="Delivery time"><select value={d.delivery_time} onChange={e => patch({ delivery_time: e.target.value })}>{['3-5 days', '7-10 days', '2 weeks', '3 weeks', '4 weeks', 'Custom'].map(x => <option key={x}>{x}</option>)}</select></Field></div><Field label="Description"><textarea value={d.description} onChange={e => patch({ description: e.target.value })} rows={3} /></Field><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={d.raw_photos_included} onChange={e => patch({ raw_photos_included: e.target.checked })} />Raw photos included</label><div className="rounded-xl border p-3"><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={d.album_included} onChange={e => patch({ album_included: e.target.checked })} />Album included</label>{d.album_included && <div className="mt-3 grid gap-3 sm:grid-cols-3"><Field label="Album type"><select value={d.album_type} onChange={e => patch({ album_type: e.target.value })}><option value="">Select</option><option>Photo book</option><option>Premium album</option><option>Digital album</option></select></Field><Field label="Album size"><input value={d.album_size} onChange={e => patch({ album_size: e.target.value })} placeholder="12×18 inches" /></Field><Field label="Pages"><input type="number" min="1" value={d.album_pages} onChange={e => patch({ album_pages: e.target.value })} /></Field></div>}</div><div className="rounded-xl border p-3"><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={d.travel_included} onChange={e => patch({ travel_included: e.target.checked })} />Travel included</label>{d.travel_included && <div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label="Included radius (km)"><input type="number" min="0" value={d.travel_radius_km} onChange={e => patch({ travel_radius_km: e.target.value })} /></Field><Field label="Extra charge beyond radius (₹)"><input type="number" min="0" value={d.travel_extra_charge} onChange={e => patch({ travel_extra_charge: e.target.value })} /></Field></div>}</div><Field label="Highlights"><div className="flex gap-2"><input value={d.highlightInput} onChange={e => patch({ highlightInput: e.target.value })} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addHighlight(); } }} placeholder="Type a highlight and press Enter" /><button type="button" onClick={addHighlight} className="rounded-lg border px-3 text-xs">Add</button></div><div className="mt-2 flex flex-wrap gap-2">{d.highlights.map((h: string) => <span key={h} className="rounded-full bg-secondary px-2 py-1 text-xs">{h}<button type="button" onClick={() => patch({ highlights: d.highlights.filter((x: string) => x !== h) })} className="ml-1"><X className="inline h-3" /></button></span>)}</div></Field><Field label="Package status"><select value={d.status} onChange={e => patch({ status: e.target.value })}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></Field><Field label="Package images"><input type="file" accept="image/*" multiple onChange={(e: ChangeEvent<HTMLInputElement>) => patch({ files: [...d.files, ...Array.from(e.target.files ?? [])] })} /><div className="mt-3 grid grid-cols-3 gap-2">{d.images.map((image: Image) => <div key={image.id} className="relative overflow-hidden rounded-lg border"><img src={image.public_url} alt="Package" className="h-20 w-full object-cover" /><div className="absolute inset-x-0 bottom-0 flex justify-between bg-black/60 p-1 text-[10px] text-white"><button type="button" onClick={() => setCover(image)}>{image.is_cover ? <><Star className="inline h-3 fill-current" /> Cover</> : 'Set cover'}</button><button type="button" onClick={() => removeImage(image)}>Delete</button></div></div>)}{d.files.map((file: File, i: number) => <div key={file.name + i} className="relative h-20 overflow-hidden rounded-lg border"><img src={URL.createObjectURL(file)} alt="New preview" className="h-full w-full object-cover" /><button type="button" onClick={() => patch({ files: d.files.filter((_: File, index: number) => index !== i) })} className="absolute right-1 top-1 rounded bg-black/60 p-1 text-white"><X className="h-3" /></button></div>)}</div></Field><Field label="Add-ons"><div className="space-y-2">{d.addons.map((a: any, i: number) => <div key={i} className="flex gap-2"><input placeholder="Add-on name" value={a.name} onChange={e => patch({ addons: d.addons.map((x: any, j: number) => j === i ? { ...x, name: e.target.value } : x) })} /><input type="number" min="0" placeholder="Price" value={a.price} onChange={e => patch({ addons: d.addons.map((x: any, j: number) => j === i ? { ...x, price: e.target.value } : x) })} /><button type="button" onClick={() => patch({ addons: d.addons.filter((_: any, j: number) => j !== i) })}><Trash2 className="h-4 text-red-600" /></button></div>)}<button type="button" onClick={() => patch({ addons: [...d.addons, { name: '', price: '' }] })} className="text-xs font-bold text-maroon"><ImagePlus className="mr-1 inline h-3" />Add add-on</button></div></Field><div className="flex gap-3"><button onClick={close} className="flex-1 rounded-xl border py-2.5">Cancel</button><button disabled={busy} onClick={save} className="flex-1 rounded-xl bg-[#8B1538] py-2.5 text-white">{busy ? 'Saving…' : 'Save package'}</button></div></div></div>; }
function Field({ label, children }: any) { return <label className="block text-sm font-medium">{label}<div className="mt-1 [&_input]:w-full [&_input]:rounded-lg [&_input]:border [&_input]:p-2 [&_select]:w-full [&_select]:rounded-lg [&_select]:border [&_select]:p-2 [&_textarea]:w-full [&_textarea]:rounded-lg [&_textarea]:border [&_textarea]:p-2">{children}</div></label>; }
